#!/usr/bin/env bash\nset -euo pipefail\n\n# In-GMT evaluation for task-specific corrected MimicLite VLA checkpoints.\n# Runs open_door and football with a MimicLite GMT backend.\n\nSCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"\nISAACLAB_ROOT="$(cd "${SCRIPT_DIR}/.." && pwd)"\n\nfind_latest_complete_model() {\n  local checkpoints_dir="$1"\n  local latest_step=-1 latest_model_path=""\n  local checkpoint_dir step candidate step_value\n  for checkpoint_dir in "${checkpoints_dir}"/*; do\n    [[ -d "${checkpoint_dir}" ]] || continue\n    step="$(basename "${checkpoint_dir}")"\n    [[ "${step}" =~ ^[0-9]+$ ]] || continue\n    candidate="${checkpoint_dir}/pretrained_model"\n    [[ -s "${candidate}/config.json" && -s "${candidate}/model.safetensors" ]] || continue\n    step_value=$((10#${step}))\n    if (( step_value > latest_step )); then\n      latest_step=${step_value}\n      latest_model_path="${candidate}"\n    fi\n  done\n  [[ -n "${latest_model_path}" ]] || {\n    echo "Error: no complete numeric checkpoint found under ${checkpoints_dir}" >&2\n    return 1\n  }\n  printf '%s' "${latest_model_path}"\n}\n\n# The two tasks are separately trained. Never reuse refpose/open_door weights\n# for football or inherit a single MODEL_PATHS_CSV for both child scripts.\nOPEN_DOOR_CHECKPOINTS_DIR="${OPEN_DOOR_CHECKPOINTS_DIR:-/ai/Yichi/zikang/mimiclite_v3.1/0726/diffusion_mimic_lite_refpose_v3_1/checkpoints}"\nFOOTBALL_CHECKPOINTS_DIR="${FOOTBALL_CHECKPOINTS_DIR:-/ai/Yichi/zikang/mimiclite_v3.1/0726/diffusion_HOI_football/checkpoints}"\nOPEN_DOOR_MODEL_PATH="${OPEN_DOOR_MODEL_PATH:-$(find_latest_complete_model "${OPEN_DOOR_CHECKPOINTS_DIR}")}"\nFOOTBALL_MODEL_PATH="${FOOTBALL_MODEL_PATH:-$(find_latest_complete_model "${FOOTBALL_CHECKPOINTS_DIR}")}"\nOPEN_DOOR_STEP="$(basename "$(dirname "${OPEN_DOOR_MODEL_PATH}")")"\nFOOTBALL_STEP="$(basename "$(dirname "${FOOTBALL_MODEL_PATH}")")"\n\n# Explicitly select the BeyondMimic/MimicLite actuator PD config. sim_eval_vla.py\n# also binds this automatically when gmt_backend=mimic_lite.\nexport MIMIC_LITE_ROBOT_CFG=1\n# Corrected refpose-v3.1 data needs no old +/-90 degree yaw workaround.\nexport VLA_MIMICLITE_YAW_CALIB_DEG=0.0\n\nexport CONDA_BASE="${CONDA_BASE:-/ai/Yichi/0_Systems/miniconda3}"\nexport CONDA_ENV_NAME="${CONDA_ENV_NAME:-unitree_sim_env}"\nexport AUTO_ACTIVATE_CONDA="${AUTO_ACTIVATE_CONDA:-1}"\nexport NUM_WORKERS="${NUM_WORKERS:-2}"\nexport RESUME_LATEST="${RESUME_LATEST:-0}"\n\nRESULTS_ROOT="${RESULTS_ROOT:-${ISAACLAB_ROOT}/script/eval_results_in_gmt_mimic_lite}"\nRUN_TS="${RUN_TS:-$(date +%Y%m%d_%H%M%S)}"\nexport RESULTS_TAG="${RESULTS_TAG:-in_gmt_mimic_lite_refpose_open${OPEN_DOOR_STEP}_football${FOOTBALL_STEP}}"\nRUN_ROOT="${RUN_ROOT:-${RESULTS_ROOT}/${RESULTS_TAG}_${RUN_TS}}"\n\necho "[mimiclite_in_gmt] open_door model=${OPEN_DOOR_MODEL_PATH}"\necho "[mimiclite_in_gmt] football model=${FOOTBALL_MODEL_PATH}"\necho "[mimiclite_in_gmt] gmt_backend=mimic_lite, MIMIC_LITE_ROBOT_CFG=${MIMIC_LITE_ROBOT_CFG}"\necho "[mimiclite_in_gmt] VLA_MIMICLITE_YAW_CALIB_DEG=${VLA_MIMICLITE_YAW_CALIB_DEG}"\necho "[mimiclite_in_gmt] run root=${RUN_ROOT}"\n\necho "[mimiclite_in_gmt] ===== open_door ====="\nexport MODEL_PATHS_CSV="${OPEN_DOOR_MODEL_PATH}"\nexport ENV_CONFIG_YAML="${OPEN_DOOR_ENV_CONFIG_YAML:-tasks/common_test_config/base_test/open_door_sonic_test.yaml}"\nexport RESULTS_DIR="${OPEN_DOOR_RESULTS_DIR:-${RUN_ROOT}/open_door}"\n"${ISAACLAB_ROOT}/script/eval_scripts/mimic_lite/HSI_open_door_run_vla_eval_parallel.sh"\n\necho "[mimiclite_in_gmt] ===== football ====="\nexport MODEL_PATHS_CSV="${FOOTBALL_MODEL_PATH}"\nexport ENV_CONFIG_YAML="${FOOTBALL_ENV_CONFIG_YAML:-tasks/common_test_config/base_test/football_single_sonic_test.yaml}"\nexport RESULTS_DIR="${FOOTBALL_RESULTS_DIR:-${RUN_ROOT}/football}"\n"${ISAACLAB_ROOT}/script/eval_scripts/mimic_lite/HOI_football_run_vla_eval_parallel.sh"\n